// Build CBSE 12 Mathematics ch09 Differential Equations. Run from platform/:
//   npx tsx content/authored/maths/cbse-12-mathematics-ch09/src/build.mjs
// Deleted for 2026-27 and absent everywhere: formation of a differential equation whose general
// solution is given (eliminating arbitrary constants).
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { setUnit, topic, deck, sl, plot, table, flow, build, chapterTests, r } from '../../cbse-12-mathematics-ch01/src/lib.mjs';
import { near, solves, rk4, od, homDegree, grid } from './ode.mjs';

setUnit('cbse-12-mathematics-ch09');
await import('./questions.mjs');
const DIR = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const ln = Math.log;

// ---------------------------------------------------------------- self-checks for every worked example
const fail = [];
const ok = (cond, msg) => { if (!cond) fail.push(msg); };
// deck 1
ok(od([[2, 2], [1, 3]]).order === 2 && od([[2, 2], [1, 3]]).degree === 2, 'D1 WE1 (i) order 2 degree 2');
ok(od([[3, 1], [1, 1]], false).order === 3 && od([[3, 1], [1, 1]], false).degree === null, 'D1 WE1 (ii) order 3, no degree');
ok(solves((x, y, y1) => y1 + y - 2 * x, (x) => Math.exp(-x) + 2 * x - 2, grid(-1, 2)), 'D1 WE2 verify');
ok([0, -0.5, 0.3].every((c) => solves((x, y, y1) => y1 - x * (1 + y * y), (x) => Math.tan((x * x) / 2 + c), grid(-1.2, 1.2), 1e-3)), 'D1 WE3 tan family');
ok(solves((x, y, y1) => y1 - y * Math.cos(x), (x) => 2 * Math.exp(Math.sin(x)), grid(-3, 3), 1e-3), 'D1 WE4 particular');
{ const k = ln(2) / 3; ok(near(rk4((t, n) => k * n, 0, 500, 9), 4000), 'D1 WE5 N(9) = 4000'); }
ok(solves((x, y, y1) => y1 - 2 * x, (x) => x * x + 2, grid(-2, 2)), 'family y = x² + C');
// deck 2
ok(homDegree((x, y) => (x * x + 3 * y * y) / (x * y)) === 0 && homDegree((x, y) => x * x + y) === null && homDegree((x, y) => Math.sqrt(x * x + y * y)) === 1 && homDegree((x, y) => (x * x * y + y ** 3) / (x + y)) === 2, 'homogeneity table');
ok(solves((x, y, y1) => y1 - y / x - x / y, (x) => Math.sqrt(2 * x * x * ln(x) + 4 * x * x), grid(0.4, 3)), 'D2 WE1 particular');
ok(solves((x, y, y1) => x * y * y1 - x * x - 2 * y * y, (x) => Math.sqrt(2 * x ** 4 - x * x), grid(0.9, 2), 1e-3), 'D2 WE2 particular');
ok([-0.5, 0, 0.5].every((c) => solves((x, y, y1) => y1 + 3 * y - Math.exp(-x), (x) => Math.exp(-x) / 2 + c * Math.exp(-3 * x), grid(-0.5, 3))), 'D2 WE3 family');
ok(solves((x, y, y1) => Math.cos(x) * y1 + y * Math.sin(x) - Math.cos(x) ** 2, (x) => (x + 2) * Math.cos(x), grid(-1.4, 1.4)), 'D2 WE4 particular');
ok([1, -2].every((c) => solves((y, x, x1) => x1 + x - y - 1, (y) => y + c * Math.exp(-y), grid(-1, 3))), 'D2 WE5 x = y + Ce^{-y}');
{ const k = ln(2) / 5; ok(near(rk4((t, T) => -k * (T - 30), 0, 90, 5), 60) && near(rk4((t, T) => -k * (T - 30), 0, 90, 10), 45), 'D2 WE6 cooling'); }
if (fail.length) throw new Error(`worked-example self-checks failed: ${fail.join('; ')}`);

// ---------------------------------------------------------------- plots (every marked point lies on its curve)
const pFamily = plot({ x: [-2.5, 2.5], y: [-3, 8], fns: [{ expr: 'x^2 - 2', label: '$C = -2$' }, { expr: 'x^2', label: '$C = 0$' }, { expr: 'x^2 + 2', label: '$C = 2$' }], pts: [[1, 3, '(1, 3)']] }, 'Three parabolas of the family y equals x squared plus C, for C equal to minus 2, 0 and 2, stacked one above another. The top curve, C equal to 2, passes through the marked point (1, 3).', r`Solutions of $\dfrac{dy}{dx} = 2x$: the general solution is a family; the condition $y(1) = 3$ picks $C = 2$.`);
const pTanFamily = plot({ x: [-1.6, 1.6], y: [-1, 8], fns: [{ expr: 'tan(x^2/2)', label: '$C = 0$' }, { expr: 'tan(x^2/2 - 0.5)', label: '$C = -0.5$' }, { expr: 'tan(x^2/2 + 0.3)', label: '$C = 0.3$' }] }, 'Three U-shaped solution curves of d y by d x equals x times one plus y squared, of the form y equals tan of x squared over 2 plus C, for C equal to minus 0.5, 0 and 0.3. Each is symmetric about the y-axis and rises steeply as x moves away from 0.', r`Members of $\tan^{-1}y = \dfrac{x^2}{2} + C$.`);
const pWE4 = plot({ x: [-4, 4], y: [0, 6], fns: [{ expr: '2*exp(sin(x))', label: r`$y = 2e^{\sin x}$` }], pts: [[0, 2, '(0, 2)']] }, 'The particular solution y equals 2 times e to the power sine x, a wave-like curve that stays above the x-axis, rising to about 5.4 and falling to about 0.74, passing through the marked starting point (0, 2).', r`The particular solution of $\dfrac{dy}{dx} = y\cos x$ through $(0, 2)$.`);
const pGrowth = plot({ x: [0, 9.5], y: [0, 4500], xl: 't (months)', yl: 'N', fns: [{ expr: '500*2^(x/3)', label: '$N = 500e^{kt}$' }], pts: [[0, 500, '(0, 500)'], [3, 1000, '(3, 1000)'], [6, 2000, '(6, 2000)'], [9, 4000, '(9, 4000)']] }, 'Exponential growth curve N equals 500 e to the power k t, rising ever more steeply. Marked points (0, 500), (3, 1000), (6, 2000) and (9, 4000) show the value doubling every 3 months.', 'Growth proportional to size: equal times give equal doublings.');
const pTitle2 = plot({ x: [-1.5, 1.5], y: [-1, 4], fns: [{ expr: 'x*cos(x)', label: '$C = 0$' }, { expr: '(x + 1)*cos(x)', label: '$C = 1$' }, { expr: '(x + 2)*cos(x)', label: '$C = 2$' }], pts: [[0, 2, '(0, 2)']] }, 'Three solution curves y equals x plus C, times cos x, for C equal to 0, 1 and 2, drawn between x equal to minus 1.5 and 1.5. The curve for C equal to 2 passes through the marked point (0, 2).', r`Solutions of $\cos x\dfrac{dy}{dx} + y\sin x = \cos^2 x$: one family, one curve through each starting point.`);
const pWE1h = plot({ x: [0.3, 3], y: [0, 9], fns: [{ expr: 'sqrt(2*x^2*ln(x) + 4*x^2)', label: r`$y^2 = 2x^2\log x + 4x^2$` }], pts: [[1, 2, '(1, 2)']] }, 'The particular solution y squared equals 2 x squared log x plus 4 x squared, a rising curve for x from 0.3 to 3, passing through the marked point (1, 2).', 'The curve through $(1, 2)$.');
const pWE2h = plot({ x: [0.7, 2.2], y: [0, 7], fns: [{ expr: 'sqrt(2*x^4 - x^2)', label: '$x^2 + y^2 = 2x^4$', domain: [0.75, 2.2] }], pts: [[1, 1, '(1, 1)']] }, 'The particular solution x squared plus y squared equals 2 x to the power 4, drawn for x from 0.75 upwards. It rises steeply and passes through the marked point (1, 1).', 'The member of $x^2 + y^2 = Ax^4$ with $A = 2$.');
const pWE3 = plot({ x: [-0.5, 3], y: [-1.5, 3.5], fns: [{ expr: 'exp(-x)/2 - 0.5*exp(-3*x)', label: '$C = -0.5$' }, { expr: 'exp(-x)/2', label: '$C = 0$' }, { expr: 'exp(-x)/2 + 0.5*exp(-3*x)', label: '$C = 0.5$' }], pts: [[0, 0.5, '(0, 0.5)'], [0, 1, '(0, 1)']] }, 'Three solution curves of d y by d x plus 3 y equals e to the minus x, for C equal to minus 0.5, 0 and 0.5. They start at different heights, the middle one at (0, 0.5) and the top one at (0, 1), and all settle towards the x-axis as x grows.', r`The $Ce^{-3x}$ part dies out quickly; every solution approaches $\dfrac12e^{-x}$.`);
const pWE4l = plot({ x: [-1.5, 1.5], y: [-0.5, 3], fns: [{ expr: '(x + 2)*cos(x)', label: '$y = (x + 2)\\cos x$' }], pts: [[0, 2, '(0, 2)']] }, 'The particular solution y equals x plus 2, times cos x, an arch-shaped curve between x equal to minus 1.5 and 1.5, passing through the marked point (0, 2).', 'The particular solution with $y(0) = 2$.');
const pCool = plot({ x: [0, 20], y: [0, 100], xl: 't (minutes)', yl: 'T (°C)', fns: [{ expr: '30 + 60*0.5^(x/5)', label: 'soup' }, { expr: '30', label: 'room, 30 °C' }], pts: [[0, 90, '(0, 90)'], [5, 60, '(5, 60)'], [10, 45, '(10, 45)'], [15, 37.5, '(15, 37.5)']] }, 'Cooling curve of a bowl of soup: temperature falls from 90 degrees at t equal to 0 to 60 at 5 minutes, 45 at 10 minutes and 37.5 at 15 minutes, levelling off towards the horizontal line for the room temperature, 30 degrees.', 'The excess over room temperature halves every 5 minutes.');
const pDrip = plot({ x: [0, 10], y: [0, 5], xl: 't (hours)', yl: 'C (mg/L)', fns: [{ expr: '4*(1 - exp(-0.5*x))', label: '$C = 4(1 - e^{-0.5t})$' }, { expr: '4', label: 'level 4' }] }, 'A rising curve that starts at the origin and levels off just below the horizontal line C equal to 4, showing a drug concentration approaching a steady level.', 'A linear equation with a constant input: the solution approaches a steady value.');

// ---------------------------------------------------------------- tables and flows
const usesTable = table(['Situation', 'Equation'], [['Bacteria in a lab culture', r`$\dfrac{dN}{dt} = kN$`], ['A cup of tea cooling', r`$\dfrac{dT}{dt} = -k(T - T_0)$`], ['A drug entering the blood by a drip', r`$\dfrac{dC}{dt} + 0.5C = 2$`], ['A curve with a given slope rule', r`$\dfrac{dy}{dx} = \dfrac{x^2 + y^2}{2xy}$`]], 'Table of situations and their differential equations: bacteria growth, d N by d t equals k N; tea cooling, d T by d t equals minus k times T minus T nought; a drug drip, d C by d t plus 0.5 C equals 2; a curve with slope x squared plus y squared over 2 x y.', 'Rates of change, written as equations.');
const orderTable = table(['Equation', 'Highest derivative', 'Order'], [[r`$\dfrac{dy}{dx} = 3x^2$`, r`$\dfrac{dy}{dx}$`, '$1$'], [r`$\dfrac{d^2y}{dx^2} + y = 0$`, r`$\dfrac{d^2y}{dx^2}$`, '$2$'], [r`$\dfrac{d^3y}{dx^3} - \left(\dfrac{dy}{dx}\right)^4 = x$`, r`$\dfrac{d^3y}{dx^3}$`, '$3$']], 'Table: d y by d x equals 3 x squared has order 1; the second derivative of y plus y equals 0 has order 2; the third derivative minus d y by d x to the power 4 equals x has order 3, because the order is set by the highest derivative, not by any power.', 'Order = order of the highest derivative.');
const degreeTable = table(['Equation', 'Polynomial in derivatives?', 'Degree'], [[r`$\left(\dfrac{d^2y}{dx^2}\right)^3 + \dfrac{dy}{dx} = 0$`, 'yes', '$3$'], [r`$\dfrac{d^2y}{dx^2} + \left(\dfrac{dy}{dx}\right)^5 = x$`, 'yes', '$1$'], [r`$\dfrac{dy}{dx} + \sin\left(\dfrac{dy}{dx}\right) = 0$`, 'no', 'not defined'], [r`$\dfrac{dy}{dx} = e^{x} + \sin x$`, r`yes ($x$-terms are allowed)`, '$1$']], 'Table of degrees: the second derivative cubed plus d y by d x has degree 3; the second derivative plus d y by d x to the power 5 has degree 1; d y by d x plus sine of d y by d x has no degree; d y by d x equals e to the x plus sine x has degree 1.', 'Degree = highest power of the highest-order derivative, only for polynomial equations.');
const we1Table = table(['', '(i)', '(ii)'], [['Highest derivative', r`$\dfrac{d^2y}{dx^2}$`, r`$\dfrac{d^3y}{dx^3}$`], ['Order', '$2$', '$3$'], ['Polynomial in derivatives?', 'yes', r`no: $\log\left(\dfrac{dy}{dx}\right)$`], ['Degree', '$2$', 'not defined']], 'Worked example table: equation one has highest derivative the second derivative, order 2, is a polynomial, degree 2; equation two has highest derivative the third derivative, order 3, is not a polynomial because of the log of d y by d x, so its degree is not defined.', 'Order first, then decide whether a degree exists.');
const verifyTable = table(['Step', 'Result'], [['$y$', r`$e^{-x} + 2x - 2$`], [r`$\dfrac{dy}{dx}$`, r`$-e^{-x} + 2$`], [r`$\dfrac{dy}{dx} + y$`, r`$-e^{-x} + 2 + e^{-x} + 2x - 2$`], ['Simplified', '$2x$ ✓']], 'Verification table: y equals e to the minus x plus 2 x minus 2; its derivative is minus e to the minus x plus 2; adding them gives 2 x, which is the right-hand side, so the function is a solution.', 'Substitute and simplify: left side equals right side.');
const constTable = table(['Order of the equation', 'Arbitrary constants in the general solution', 'Example'], [['$1$', '$1$', r`$y = x^2 + C$`], ['$2$', '$2$', r`$y = Ae^{2x} + Be^{-2x}$`], ['$3$', '$3$', r`$y = A + Bx + Cx^2$`]], 'Table: an equation of order 1 has 1 arbitrary constant in its general solution, for example y equals x squared plus C; order 2 has 2 constants; order 3 has 3 constants.', 'As many arbitrary constants as the order.');
const sepFlow = flow('TB', [['a', r`Write $\dfrac{dy}{dx} = g(x)\,h(y)$`], ['b', r`Separate: $\dfrac{dy}{h(y)} = g(x)\,dx$`], ['c', 'Integrate both sides; add one constant $C$'], ['d', 'Simplify (combine logs, exponentiate)'], ['e', 'Initial condition given? Find $C$']], [['a', 'b'], ['b', 'c'], ['c', 'd'], ['d', 'e']], 'Flow chart for variables separable: write d y by d x as g of x times h of y; separate into d y over h of y equals g of x d x; integrate both sides with one constant; simplify; if an initial condition is given, find C.', 'Variables separable in five steps.');
const growthTable = table(['$t$ (months)', '$0$', '$3$', '$6$', '$9$'], [['$N$', '$500$', '$1000$', '$2000$', '$4000$']], 'Table of followers: 500 at 0 months, 1000 at 3 months, 2000 at 6 months and 4000 at 9 months; the number doubles every 3 months.', r`Since $e^{3k} = 2$, every $3$ months multiplies $N$ by $2$.`);
const homTable = table(['$F(x, y)$', r`$F(\lambda x, \lambda y)$`, 'Homogeneous?'], [[r`$\dfrac{x^2 + 3y^2}{xy}$`, r`$\lambda^0F(x, y)$`, 'yes, degree $0$'], [r`$\sqrt{x^2 + y^2}$`, r`$\lambda F(x, y)$`, 'yes, degree $1$'], [r`$\dfrac{x^2y + y^3}{x + y}$`, r`$\lambda^2F(x, y)$`, 'yes, degree $2$'], [r`$x^2 + y$`, r`$\lambda^2x^2 + \lambda y$`, 'no']], 'Table testing homogeneity: x squared plus 3 y squared over x y gives lambda to the power 0 times F, degree 0; the square root of x squared plus y squared gives lambda times F, degree 1; x squared y plus y cubed over x plus y gives lambda squared times F, degree 2; x squared plus y is not homogeneous.', r`Replace $x, y$ by $\lambda x, \lambda y$ and try to pull out $\lambda^n$.`);
const homFlow = flow('TB', [['a', r`Check $\dfrac{dy}{dx} = F(x, y)$ with $F$ of degree $0$`], ['b', r`Put $y = vx$, $\dfrac{dy}{dx} = v + x\dfrac{dv}{dx}$`], ['c', r`Simplify to $x\dfrac{dv}{dx} = g(v)$`], ['d', r`Separate: $\dfrac{dv}{g(v)} = \dfrac{dx}{x}$ and integrate`], ['e', r`Replace $v$ by $\dfrac{y}{x}$`]], [['a', 'b'], ['b', 'c'], ['c', 'd'], ['d', 'e']], 'Flow chart for a homogeneous equation: check that the right side has degree 0; put y equals v x, so d y by d x equals v plus x d v by d x; simplify to x d v by d x equals g of v; separate and integrate; replace v by y over x.', 'Homogeneous equations become separable after $y = vx$.');
const linFlow = flow('TB', [['a', r`Write $\dfrac{dy}{dx} + Py = Q$ ($P$, $Q$ functions of $x$)`], ['b', r`Integrating factor: $\text{I.F.} = e^{\int P\,dx}$`], ['c', r`Multiply: $\dfrac{d}{dx}\left(y \cdot \text{I.F.}\right) = Q \cdot \text{I.F.}$`], ['d', r`Integrate: $y \cdot \text{I.F.} = \int Q \cdot \text{I.F.}\,dx + C$`]], [['a', 'b'], ['b', 'c'], ['c', 'd']], 'Flow chart for a linear equation: write it as d y by d x plus P y equals Q; find the integrating factor, e to the power integral of P; multiply so that the left side becomes the derivative of y times the integrating factor; integrate both sides and add C.', 'The integrating factor turns the left side into one derivative.');
const ifTable = table(['$P(x)$', r`$\int P\,dx$`, 'Integrating factor'], [['$3$', '$3x$', '$e^{3x}$'], [r`$\dfrac{1}{x}$`, r`$\log x$`, '$x$'], [r`$\dfrac{2}{x}$`, r`$2\log x$`, '$x^2$'], [r`$-\dfrac{1}{x}$`, r`$-\log x$`, r`$\dfrac{1}{x}$`], [r`$\tan x$`, r`$\log \sec x$`, r`$\sec x$`], [r`$\dfrac{2x}{1 + x^2}$`, r`$\log(1 + x^2)$`, '$1 + x^2$']], 'Table of common integrating factors: P equal to 3 gives e to the 3 x; 1 over x gives x; 2 over x gives x squared; minus 1 over x gives 1 over x; tan x gives sec x; 2 x over 1 plus x squared gives 1 plus x squared.', r`$e^{\log f(x)} = f(x)$ does most of the work.`);
const linXTable = table(['', 'Linear in $y$', 'Linear in $x$'], [['Form', r`$\dfrac{dy}{dx} + Py = Q$`, r`$\dfrac{dx}{dy} + Px = Q$`], ['$P$, $Q$ depend on', '$x$ only', '$y$ only'], ['Integrating factor', r`$e^{\int P\,dx}$`, r`$e^{\int P\,dy}$`], ['Solution', r`$y \cdot \text{I.F.} = \int Q \cdot \text{I.F.}\,dx + C$`, r`$x \cdot \text{I.F.} = \int Q \cdot \text{I.F.}\,dy + C$`]], 'Comparison table: linear in y has the form d y by d x plus P y equals Q with P and Q functions of x, integrating factor e to the integral of P d x; linear in x has d x by d y plus P x equals Q with P and Q functions of y, integrating factor e to the integral of P d y.', 'Same method, roles of $x$ and $y$ swapped.');
const we5Table = table(['Step', 'Result'], [['Form', r`$\dfrac{dx}{dy} + x = y + 1$: $P = 1$, $Q = y + 1$`], ['Integrating factor', '$e^{y}$'], ['Integrate', r`$xe^{y} = \int (y + 1)e^{y}\,dy = ye^{y} + C$`], ['Solution', r`$x = y + Ce^{-y}$`]], 'Worked example table: the equation d x by d y plus x equals y plus 1 has P equal to 1 and Q equal to y plus 1; the integrating factor is e to the y; integrating y plus 1 times e to the y by parts gives y e to the y plus C; so x equals y plus C e to the minus y.', 'Linear in $x$: integrate with respect to $y$.');
const methodFlow = flow('TB', [['s', r`First-order, first-degree equation $\dfrac{dy}{dx} = F(x, y)$`], ['q1', r`Can $F$ be written as $g(x)\,h(y)$?`], ['sep', 'Variables separable'], ['q2', r`Is $F$ homogeneous of degree $0$?`], ['hom', r`Homogeneous: put $y = vx$`], ['q3', r`Is it $\dfrac{dy}{dx} + Py = Q$, or $\dfrac{dx}{dy} + Px = Q$?`], ['lin', 'Linear: use the integrating factor']], [['s', 'q1'], ['q1', 'sep', 'yes'], ['q1', 'q2', 'no'], ['q2', 'hom', 'yes'], ['q2', 'q3', 'no'], ['q3', 'lin', 'yes']], 'Decision chart: for a first-order first-degree equation, first ask whether the right side is a product of a function of x and a function of y; if yes, separate the variables. If not, ask whether it is homogeneous of degree 0; if yes, put y equals v x. If not, ask whether it is linear in y or in x; if yes, use an integrating factor.', 'Which method? Ask three questions in order.');
const sum1 = table(['Idea', 'Key fact'], [['Order', 'Order of the highest derivative'], ['Degree', 'Power of the highest-order derivative; defined only for a polynomial in derivatives'], ['General solution', 'Has as many arbitrary constants as the order'], ['Particular solution', 'Constants fixed, usually by an initial condition'], ['Variables separable', r`$\int \dfrac{dy}{h(y)} = \int g(x)\,dx + C$`], ['Growth or decay', r`$\dfrac{dN}{dt} = kN \Rightarrow N = N_0e^{kt}$`]], 'Summary table for part 1: order is the order of the highest derivative; degree is the power of the highest-order derivative when the equation is a polynomial in derivatives; the general solution has as many constants as the order; a particular solution fixes them; variables separable means integrate each side; growth or decay gives N equals N nought e to the k t.', 'Part 1 on one card.');
const sum2 = table(['Type', 'Recognise it by', 'Method'], [['Homogeneous', r`$F(\lambda x, \lambda y) = F(x, y)$`, r`$y = vx$, then separate`], ['Linear in $y$', r`$\dfrac{dy}{dx} + Py = Q$, $P, Q$ in $x$`, r`I.F. $= e^{\int P\,dx}$`], ['Linear in $x$', r`$\dfrac{dx}{dy} + Px = Q$, $P, Q$ in $y$`, r`I.F. $= e^{\int P\,dy}$`]], 'Summary table for part 2: homogeneous equations, where F of lambda x, lambda y equals F of x, y, are solved by y equals v x and separation; linear equations in y use the integrating factor e to the integral of P d x; linear equations in x use e to the integral of P d y.', 'Part 2 on one card.');

// ---------------------------------------------------------------- deck 1
const d1 = deck({
  part: 1,
  title: 'Differential Equations — Part 1: Order, degree, solutions and separable equations',
  goals: ['Find the order and degree of a differential equation, and recognise when the degree is not defined', 'Distinguish general and particular solutions and verify a solution', 'Solve equations with separable variables', 'Use separable equations for growth and decay'],
  slides: [
    sl('title', 'Differential Equations, Part 1', { b: 'Equations whose unknown is a function.', v: pFamily, n: 'Welcome. So far, equations had numbers as answers. Now the unknown is a whole function. If you know how a quantity changes, can you find the quantity itself? On the screen, three parabolas all have the same slope rule: the slope is two x. One rule gives a whole family of curves, and one starting point picks out a single curve.' }),
    sl('concept', 'What you will be able to do', { ul: ['Find the **order** and **degree** of a differential equation', 'Tell **general** and **particular** solutions apart and **verify** a solution', 'Solve equations by **separating the variables**', 'Model **growth and decay**'], v: usesTable, n: 'Here are the goals for part one. Differential equations appear wherever something changes: bacteria multiplying, tea cooling, a medicine entering the blood. By the end of this part you will be able to describe such an equation, check a proposed solution, and solve the simplest kind, where the variables can be separated.' }),
    sl('concept', 'What is a differential equation?', { b: r`A **differential equation** is an equation involving an unknown function and one or more of its derivatives, such as $\dfrac{dy}{dx} = 2x$ or $\dfrac{d^2y}{dx^2} + 4y = 0$.`, ul: [r`Here $y$ depends on one variable $x$: an **ordinary** differential equation`, r`We write $y'$, $y''$ for $\dfrac{dy}{dx}$, $\dfrac{d^2y}{dx^2}$`], n: 'A differential equation links an unknown function with its derivatives. In this chapter, y always depends on a single variable x, so the equations are called ordinary differential equations. We often write y dash for the first derivative and y double dash for the second. Solving means finding every function that makes the equation true.' }),
    sl('concept', 'Order of a differential equation', { b: 'The **order** is the order of the **highest derivative** that appears.', v: orderTable, n: 'The order tells you how many times the unknown function has been differentiated, at most. Look for the highest derivative. If the third derivative appears, the order is three, even if a lower derivative is raised to the fourth power. Powers never decide the order; only the highest derivative does.' }),
    sl('concept', 'Degree of a differential equation', { b: 'If the equation is a **polynomial in its derivatives**, its **degree** is the highest power of the **highest-order** derivative. Otherwise the degree is **not defined**.', v: degreeTable, n: 'Degree needs more care. First ask: is the equation a polynomial in the derivatives? If a derivative sits inside a sine, a logarithm or an exponential, the answer is no, and the degree is not defined. If the answer is yes, look only at the highest-order derivative and read its power. Functions of x alone, like sine x, are allowed.' }),
    sl('example', 'Worked example 1: order and degree', { b: r`Find the order and degree: **(i)** $\left(\dfrac{d^2y}{dx^2}\right)^2 + 3x\left(\dfrac{dy}{dx}\right)^3 = \sin x$; **(ii)** $\dfrac{d^3y}{dx^3} + \log\left(\dfrac{dy}{dx}\right) = 0$.`, ul: [r`**(i)** Highest derivative $\dfrac{d^2y}{dx^2}$: order $2$. Polynomial in derivatives; power of $\dfrac{d^2y}{dx^2}$ is $2$: **degree $2$** (not $3$).`, r`**(ii)** Highest derivative $\dfrac{d^3y}{dx^3}$: order $3$. The $\log\left(\dfrac{dy}{dx}\right)$ term is not polynomial: **degree not defined**.`], v: we1Table, n: 'In the first equation the highest derivative is the second, so the order is two. It is a polynomial in the derivatives, and the second derivative is squared, so the degree is two. The cube on the first derivative is a trap. In the second equation the order is three, but the logarithm of a derivative means the degree is not defined.' }),
    sl('check', 'Quick check: order or degree?', { b: 'Do you know which word means what?', chk: 'tf1', n: 'Recall the two definitions. One of them is about which derivative is highest. The other is about a power. Decide which description matches the statement.' }),
    sl('concept', 'General and particular solutions', { b: r`A **solution** is a function that satisfies the equation. The **general solution** contains arbitrary constants; a **particular solution** has them fixed, often by an **initial condition** such as $y(1) = 3$.`, v: pFamily, n: 'For d y by d x equals two x, every function x squared plus C is a solution. That is the general solution, a whole family of curves. If we also know that the curve passes through one comma three, then C must be two. That single curve is a particular solution. Conditions like this are called initial conditions.' }),
    sl('example', 'Worked example 2: verifying a solution', { b: r`Verify that $y = e^{-x} + 2x - 2$ is a solution of $\dfrac{dy}{dx} + y = 2x$.`, ul: [r`**Differentiate:** $\dfrac{dy}{dx} = -e^{-x} + 2$`, r`**Substitute:** $\dfrac{dy}{dx} + y = -e^{-x} + 2 + e^{-x} + 2x - 2$`, r`**Simplify:** $= 2x$, the right side ✓`], v: verifyTable, n: 'To verify a solution, you never solve the equation. You differentiate the given function, substitute into the left side, and simplify. Here the exponential terms cancel and the constants cancel, leaving two x, which is exactly the right side. So the function is a solution. Always show both sides clearly.' }),
    sl('concept', 'How many arbitrary constants?', { b: 'The general solution of an equation of **order $n$** contains **$n$ independent arbitrary constants**. A particular solution contains **none**.', v: constTable, n: 'There is a simple count to remember. A first-order equation has one arbitrary constant in its general solution. A second-order equation has two, and so on. A particular solution has no arbitrary constants left, because conditions have fixed them all. This count helps you check an answer quickly in multiple choice questions.' }),
    sl('check', 'Quick check: counting constants', { b: 'Link the order to the constants.', chk: 'm04', n: 'Think about the rule you just saw: the number of arbitrary constants matches one property of the equation. Which number goes with an equation of order three?' }),
    sl('check', 'Quick check: from general to particular', { b: 'How do we get a particular solution?', chk: 'm06', n: 'A particular solution is one member of the family. Ask yourself what changes when we move from the whole family to one curve.' }),
    sl('concept', 'Variables separable: the method', { b: r`If $\dfrac{dy}{dx} = g(x)\,h(y)$, bring all $y$ terms to one side and all $x$ terms to the other, then integrate.`, v: sepFlow, n: 'The simplest equations to solve are those where the right side is a function of x times a function of y. Divide by the y part, multiply by d x, and the variables are separated. Then integrate each side. Add just one constant, on one side. Finally, simplify, and use an initial condition if one is given.' }),
    sl('example', 'Worked example 3: a general solution', { b: r`Solve $\dfrac{dy}{dx} = x(1 + y^2)$.`, ul: [r`**Separate:** $\dfrac{dy}{1 + y^2} = x\,dx$`, r`**Integrate:** $\tan^{-1}y = \dfrac{x^2}{2} + C$`, r`**Explicit form:** $y = \tan\left(\dfrac{x^2}{2} + C\right)$`], v: pTanFamily, n: 'The right side is x times one plus y squared, a product, so the variables separate. Divide by one plus y squared. The left side integrates to tan inverse y, and the right side to x squared over two. Add one constant. Each value of C gives one curve of the family shown on the screen.' }),
    sl('example', 'Worked example 4: a particular solution', { b: r`Solve $\dfrac{dy}{dx} = y\cos x$, given $y(0) = 2$ ($y > 0$).`, ul: [r`**Separate:** $\dfrac{dy}{y} = \cos x\,dx$`, r`**Integrate:** $\log y = \sin x + C$`, r`**Condition:** $x = 0$, $y = 2$ gives $C = \log 2$`, r`**Answer:** $y = 2e^{\sin x}$`], v: pWE4, n: 'Divide by y and multiply by d x. The left side gives log y and the right side gives sine x. Now use the condition: when x is zero, y is two, so C equals log two. Combining the logarithms, y equals two times e to the power sine x. The graph confirms that the curve passes through zero comma two.' }),
    sl('check', 'Quick check: an initial-value problem', { b: 'Solve and substitute.', chk: 'n06', n: 'Separate the variables, integrate, and use the starting value to find the constant. Then substitute the given value of x. You should recognise the function you get.' }),
    sl('diagram', 'Growth proportional to size', { b: r`If a quantity grows at a rate proportional to itself, $\dfrac{dN}{dt} = kN$ with $k > 0$. Separating gives $N = N_0e^{kt}$. For decay, $k < 0$.`, v: pGrowth, n: 'Many real quantities grow in proportion to their size: the bigger they are, the faster they grow. Separating the variables gives an exponential. A key feature is that the quantity doubles in equal time intervals. On this graph it doubles every three months: five hundred, one thousand, two thousand, four thousand.' }),
    sl('example', 'Worked example 5: followers of a food blog', { b: r`A Lucknow food blog's followers $N$ grow so that $\dfrac{dN}{dt} = kN$ ($t$ in months). There were $500$ followers at the start and $1000$ after $3$ months. How many after $9$ months?`, ul: [r`**Solve:** $N = 500e^{kt}$`, r`**Second fact:** $1000 = 500e^{3k}$, so $e^{3k} = 2$`, r`**Predict:** $N(9) = 500\left(e^{3k}\right)^3 = 500 \times 8 = 4000$`], v: growthTable, n: 'Solving gives N equals five hundred times e to the k t. The second piece of information gives e to the three k equals two. We do not even need k itself. Nine months is three lots of three months, so multiply by two, three times. The blog should have four thousand followers.' }),
    sl('summary', 'Summary of Part 1', { b: 'The key ideas on one card.', v: sum1, n: 'To sum up. The order is the highest derivative; the degree is its power, and exists only for polynomial equations. A general solution has as many constants as the order, and a particular solution fixes them. If the variables separate, integrate each side. Growth in proportion to size gives an exponential.' }),
    sl('exam-tips', 'Exam tips for Part 1', { ul: ['Order: read the highest derivative, ignore powers', 'Degree: first check that the equation is a polynomial in derivatives; else write "not defined"', 'Verify a solution by differentiating and substituting, showing both sides', 'Add the constant of integration once, and use the initial condition only after integrating', 'Write $\\log|y|$ where $y$ may be negative', 'Not in the 2026–27 syllabus: forming a differential equation by eliminating constants'], n: 'Some exam advice. For order, look only at the highest derivative. For degree, always check first whether a degree exists. When verifying, show the derivative and both sides. When separating, add one constant and use the condition at the end. And remember: forming a differential equation from a given family is not in this year\'s syllabus.' }),
  ],
});

// ---------------------------------------------------------------- deck 2
const d2 = deck({
  part: 2,
  title: 'Differential Equations — Part 2: Homogeneous and linear equations',
  goals: ['Test a function for homogeneity and find its degree', 'Solve homogeneous equations with the substitution y = vx', 'Solve linear equations dy/dx + Py = Q with an integrating factor', 'Solve equations linear in x and choose the right method'],
  slides: [
    sl('title', 'Differential Equations, Part 2', { b: 'Two new types, two new tools.', v: pTitle2, n: 'Welcome to part two. Not every equation separates at once. In this part you will meet two important types: homogeneous equations, which become separable after a clever substitution, and linear equations, which are solved with a multiplier called the integrating factor. On the screen is a family of solutions of a linear equation.' }),
    sl('concept', 'What you will be able to do', { ul: ['Test whether a function is **homogeneous**', 'Solve **homogeneous** equations with $y = vx$', 'Solve **linear** equations with an **integrating factor**', 'Handle equations **linear in $x$**, and **choose a method**'], v: sum2, n: 'Here are the goals for part two. You will learn to recognise each type by its form and to apply the matching method. The table on the screen is a preview of the whole part. By the end, you should be able to look at any first-order equation in the syllabus and decide quickly how to solve it.' }),
    sl('concept', 'Homogeneous functions', { b: r`$F(x, y)$ is **homogeneous of degree $n$** if $F(\lambda x, \lambda y) = \lambda^n F(x, y)$ for all non-zero $\lambda$.`, v: homTable, n: 'Replace x by lambda x and y by lambda y. If you can pull out lambda to some power n, leaving the original function, the function is homogeneous of degree n. Every term must have the same total degree. A constant term, or terms of different degrees such as x squared plus y, spoil it.' }),
    sl('diagram', 'Homogeneous equations and the substitution', { b: r`$\dfrac{dy}{dx} = F(x, y)$ is **homogeneous** if $F$ is homogeneous of **degree $0$**; then $F$ depends only on $\dfrac{y}{x}$. Put $y = vx$.`, v: homFlow, n: 'An equation d y by d x equals F is called homogeneous when F has degree zero. Then F is really a function of y over x alone. So we put y equals v x, where v is a new unknown function. By the product rule, d y by d x becomes v plus x d v by d x. After simplifying, the variables v and x separate.' }),
    sl('example', 'Worked example 1: a homogeneous equation', { b: r`Solve $\dfrac{dy}{dx} = \dfrac{y}{x} + \dfrac{x}{y}$, $x > 0$, given $y(1) = 2$.`, ul: [r`**Substitute:** $v + x\dfrac{dv}{dx} = v + \dfrac1v$, so $v\,dv = \dfrac{dx}{x}$`, r`**Integrate:** $\dfrac{v^2}{2} = \log x + C$, i.e. $y^2 = 2x^2\log x + 2Cx^2$`, r`**Condition:** $4 = 0 + 2C$, so $2C = 4$`, r`**Answer:** $y^2 = 2x^2\log x + 4x^2$`], v: pWE1h, n: 'The right side has degree zero, so put y equals v x. The v terms cancel, leaving x d v by d x equals one over v. Separate and integrate: v squared over two equals log x plus C. Replace v by y over x and multiply by two x squared. Finally, the condition at x equals one fixes the constant.' }),
    sl('example', 'Worked example 2: simplify before separating', { b: r`Solve $xy\dfrac{dy}{dx} = x^2 + 2y^2$, $x > 0$, given $y(1) = 1$.`, ul: [r`**Form:** $\dfrac{dy}{dx} = \dfrac{x^2 + 2y^2}{xy}$; put $y = vx$: $v + x\dfrac{dv}{dx} = \dfrac{1}{v} + 2v$`, r`**Simplify:** $x\dfrac{dv}{dx} = \dfrac{1 + v^2}{v}$, so $\dfrac{v\,dv}{1 + v^2} = \dfrac{dx}{x}$`, r`**Integrate:** $\dfrac12\log(1 + v^2) = \log x + C$, so $1 + v^2 = Ax^2$, i.e. $x^2 + y^2 = Ax^4$`, r`**Condition:** $1 + 1 = A$: $x^2 + y^2 = 2x^4$`], v: pWE2h, n: 'Divide to get d y by d x on its own, then put y equals v x. Subtract v carefully: two v minus v leaves v, so x d v by d x equals one plus v squared, all over v. Separate. The left side is half the derivative of the log of one plus v squared. Clear the logarithms, return to x and y, and use the point one comma one.' }),
    sl('check', 'Quick check: the substitution', { b: 'Which substitution?', chk: 'm13', n: 'For a homogeneous equation, the right side depends only on the ratio of y to x. Which substitution makes that ratio a single new variable?' }),
    sl('check', 'Quick check: the product rule', { b: 'Differentiate the substitution.', chk: 'm14', n: 'Remember that v is a function of x, not a constant. Use the product rule on v times x.' }),
    sl('concept', 'Linear equations and the integrating factor', { b: r`A **linear** equation has the form $\dfrac{dy}{dx} + Py = Q$, with $P$, $Q$ functions of $x$ (or constants). Multiply by $\text{I.F.} = e^{\int P\,dx}$.`, v: linFlow, n: 'In a linear equation, y and its derivative appear only to the first power and are never multiplied together. Write it in the standard form, d y by d x plus P y equals Q. Then multiply both sides by the integrating factor, e to the power integral of P. The left side becomes the derivative of y times the integrating factor, so one integration finishes the job.' }),
    sl('diagram', 'Common integrating factors', { b: r`Use $e^{\log f(x)} = f(x)$ to simplify. No constant is needed inside $\int P\,dx$.`, v: ifTable, n: 'Here are integrating factors you will meet again and again. Notice how often the integral of P is a logarithm, so the exponential and the logarithm cancel. Do not add a constant when you integrate P: any one integrating factor works. And always put the equation in standard form first, or P will have the wrong sign or the wrong coefficient.' }),
    sl('example', 'Worked example 3: a constant coefficient', { b: r`Solve $\dfrac{dy}{dx} + 3y = e^{-x}$.`, ul: [r`**I.F.:** $P = 3$, so $\text{I.F.} = e^{3x}$`, r`**Multiply:** $\dfrac{d}{dx}\left(ye^{3x}\right) = e^{-x}e^{3x} = e^{2x}$`, r`**Integrate:** $ye^{3x} = \dfrac{e^{2x}}{2} + C$`, r`**Answer:** $y = \dfrac{e^{-x}}{2} + Ce^{-3x}$`], v: pWE3, n: 'Here P is the constant three, so the integrating factor is e to the three x. Multiplying, the left side becomes the derivative of y times e to the three x, and the right side simplifies to e to the two x. Integrate and divide by e to the three x. The graph shows that, whatever C is, the solutions settle down together.' }),
    sl('example', 'Worked example 4: trigonometric coefficients', { b: r`Solve $\cos x\dfrac{dy}{dx} + y\sin x = \cos^2 x$, $|x| < \dfrac{\pi}{2}$, given $y(0) = 2$.`, ul: [r`**Standard form:** divide by $\cos x$: $\dfrac{dy}{dx} + y\tan x = \cos x$`, r`**I.F.:** $e^{\int \tan x\,dx} = e^{\log \sec x} = \sec x$`, r`**Integrate:** $\dfrac{d}{dx}(y\sec x) = \cos x \sec x = 1$, so $y\sec x = x + C$`, r`**Condition:** $2 = C$, so $y = (x + 2)\cos x$`], v: pWE4l, n: 'First divide by cos x to reach standard form, so P is tan x and Q is cos x. The integrating factor is sec x. Multiplying, the right side becomes cos x times sec x, which is one. So y sec x equals x plus C. At x equals zero, sec x is one and y is two, so C is two.' }),
    sl('check', 'Quick check: finding the integrating factor', { b: 'Mind the sign of $P$.', chk: 'm15', n: 'Identify P carefully, including its sign. Integrate it, and simplify e to the power of a logarithm.' }),
    sl('concept', 'Equations linear in x', { b: r`Sometimes the equation is linear in $x$: $\dfrac{dx}{dy} + Px = Q$, with $P$, $Q$ functions of $y$. Use $\text{I.F.} = e^{\int P\,dy}$.`, v: linXTable, n: 'Sometimes it is easier to treat x as the unknown function of y. Then the standard form is d x by d y plus P x equals Q, where P and Q depend only on y. Everything works the same way, with the roles of x and y swapped. The integrating factor is e to the power integral of P d y.' }),
    sl('example', 'Worked example 5: linear in x', { b: r`Solve $\dfrac{dx}{dy} + x = y + 1$.`, ul: [r`$P = 1$, $Q = y + 1$; $\text{I.F.} = e^{y}$`, r`$\dfrac{d}{dy}\left(xe^{y}\right) = (y + 1)e^{y}$`, r`By parts: $\int (y + 1)e^{y}\,dy = ye^{y} + C$`, r`**Answer:** $x = y + Ce^{-y}$`], v: we5Table, n: 'Here x is the unknown, and P equals one, so the integrating factor is e to the y. Multiplying, the left side becomes the derivative of x e to the y with respect to y. Integrate y plus one times e to the y by parts: it gives y times e to the y. Divide by e to the y to finish.' }),
    sl('check', 'Quick check: linear in x', { b: 'Which variable does the integrating factor depend on?', chk: 'm17', n: 'In this form, x is the dependent variable. The integrating factor must be built from P, a function of y, by integrating with respect to y.' }),
    sl('diagram', 'Which method?', { b: 'Ask three questions in order: separable? homogeneous? linear?', v: methodFlow, n: 'When you meet a new equation, ask in order. Can the right side be written as a function of x times a function of y? Then separate. If not, is it homogeneous of degree zero? Then put y equals v x. If not, is it linear in y, or linear in x? Then use an integrating factor. Some equations fit two types; either method then works.' }),
    sl('example', 'Worked example 6: a bowl of soup cools', { b: r`A bowl of soup at $90$ °C is in a room at $30$ °C, and $\dfrac{dT}{dt} = -k(T - 30)$. After $5$ minutes it is at $60$ °C. Find its temperature after $10$ minutes.`, ul: [r`**Separate:** $\dfrac{dT}{T - 30} = -k\,dt$, so $T - 30 = Ae^{-kt}$; $T(0) = 90$ gives $A = 60$`, r`**After 5 minutes:** $60 - 30 = 60e^{-5k}$, so $e^{-5k} = \dfrac12$`, r`**Predict:** $T(10) = 30 + 60\left(e^{-5k}\right)^2 = 30 + 60 \times \dfrac14 = 45$ °C`], v: pCool, n: 'This equation is separable, and also linear. Separating gives T minus thirty equals A e to the minus k t, and the starting temperature gives A equals sixty. After five minutes the excess over room temperature has halved. Ten minutes is two halvings, so the excess is fifteen degrees, and the soup is at forty five degrees.' }),
    sl('summary', 'Summary of Part 2', { b: 'The key ideas on one card.', v: sum2, n: 'To sum up. A homogeneous equation has a right side of degree zero; put y equals v x and separate. A linear equation in y uses the integrating factor e to the integral of P d x. A linear equation in x uses e to the integral of P d y. Always reach standard form before reading off P.' }),
    sl('exam-tips', 'Exam tips for Part 2', { ul: ['Show the homogeneity test $F(\\lambda x, \\lambda y)$ before substituting', 'After $y = vx$, return to $x$ and $y$ in the final answer', 'Write the standard form first; read $P$ with its sign', 'No constant inside the integrating factor; one constant after the final integration', 'Check a particular solution against the initial condition', 'Typical marks: 2 for a short type check or integrating factor, 3 for a solution, 5 for a particular solution with steps'], n: 'Final tips. For homogeneous equations, show the test with lambda, and give the answer in x and y, not v. For linear equations, write the standard form before reading P, and keep track of the sign. Use one constant, at the end. And check your particular solution against the given condition; it takes only a few seconds.' }),
  ],
});

// ---------------------------------------------------------------- notes
const notes = {
  unit: 'cbse-12-mathematics-ch09', version: 1, title: 'Differential Equations — chapter notes', language: 'en',
  sections: [
    { heading: '1. Differential equations and their order', body_md: r`A **differential equation** is an equation involving an unknown function and its derivatives. When the unknown $y$ depends on one variable $x$ it is an **ordinary** differential equation, e.g. $\dfrac{dy}{dx} = 3x^2$, $\dfrac{d^2y}{dx^2} + y = 0$.

The **order** is the order of the highest derivative present. Powers do not affect the order: $\dfrac{d^3y}{dx^3} - \left(\dfrac{dy}{dx}\right)^4 = x$ has order $3$.`, key_terms: [{ term: 'Differential equation', definition_md: 'An equation involving an unknown function and its derivatives.' }, { term: 'Order', definition_md: 'The order of the highest derivative that appears.' }], formulas: [{ latex: r`y' = \dfrac{dy}{dx}, \quad y'' = \dfrac{d^2y}{dx^2}`, label: 'Notation' }], visual: orderTable, topic_ids: [topic(1)] },
    { heading: '2. Degree', body_md: r`If a differential equation is a **polynomial in its derivatives**, its **degree** is the highest power (a positive integer) of the highest-order derivative.

- $\left(\dfrac{d^2y}{dx^2}\right)^2 + 3x\left(\dfrac{dy}{dx}\right)^3 = \sin x$: order $2$, degree $2$.
- $\dfrac{d^3y}{dx^3} + \log\left(\dfrac{dy}{dx}\right) = 0$: order $3$, degree **not defined**.

Functions of $x$ alone ($\sin x$, $e^{x}$, $\log x$) do not stop the degree from being defined; a derivative inside such a function does.`, key_terms: [{ term: 'Degree', definition_md: 'Highest power of the highest-order derivative, when the equation is a polynomial in derivatives.' }], formulas: [], visual: degreeTable, topic_ids: [topic(1)] },
    { heading: '3. General and particular solutions', body_md: r`A **solution** is a function that satisfies the equation. The **general solution** contains arbitrary constants, as many (independent) as the order. A **particular solution** has all constants fixed, usually by an **initial condition** like $y(x_0) = y_0$.

To **verify** that a given function is a solution: differentiate it, substitute into the equation, and show that both sides agree. Example: $y = e^{-x} + 2x - 2$ satisfies $\dfrac{dy}{dx} + y = 2x$.

*Not in the 2026–27 syllabus:* forming a differential equation from a given family by eliminating arbitrary constants.`, key_terms: [{ term: 'General solution', definition_md: 'A solution containing as many arbitrary constants as the order.' }, { term: 'Particular solution', definition_md: 'A solution with no arbitrary constants, chosen by given conditions.' }, { term: 'Initial condition', definition_md: r`A condition such as $y(0) = 2$ that fixes a constant.` }], formulas: [], visual: pFamily, visuals: [verifyTable], topic_ids: [topic(1)] },
    { heading: '4. Variables separable', body_md: r`If $\dfrac{dy}{dx} = g(x)\,h(y)$, separate and integrate:

$$\int \dfrac{dy}{h(y)} = \int g(x)\,dx + C.$$

Examples: $\dfrac{dy}{dx} = x(1 + y^2)$ gives $\tan^{-1}y = \dfrac{x^2}{2} + C$; $\dfrac{dy}{dx} = y\cos x$ with $y(0) = 2$ gives $y = 2e^{\sin x}$.

**Growth and decay:** $\dfrac{dN}{dt} = kN$ gives $N = N_0e^{kt}$. Equal time intervals multiply $N$ by equal factors.`, key_terms: [{ term: 'Separable equation', definition_md: r`One that can be written as $\dfrac{dy}{dx} = g(x)h(y)$.` }], formulas: [{ latex: r`\dfrac{dN}{dt} = kN \;\Rightarrow\; N = N_0e^{kt}`, label: 'Growth or decay' }], visual: sepFlow, visuals: [pGrowth], topic_ids: [topic(2)] },
    { heading: '5. Homogeneous equations', body_md: r`$F(x, y)$ is **homogeneous of degree $n$** if $F(\lambda x, \lambda y) = \lambda^nF(x, y)$. The equation $\dfrac{dy}{dx} = F(x, y)$ is **homogeneous** when $F$ has degree $0$.

**Method:** put $y = vx$, so $\dfrac{dy}{dx} = v + x\dfrac{dv}{dx}$; simplify to $x\dfrac{dv}{dx} = g(v)$; separate $\dfrac{dv}{g(v)} = \dfrac{dx}{x}$; integrate; replace $v$ by $\dfrac{y}{x}$.

Example: $xy\dfrac{dy}{dx} = x^2 + 2y^2$ gives $x^2 + y^2 = Ax^4$; with $y(1) = 1$, $A = 2$.

(For $\dfrac{dx}{dy} = G(x, y)$ with $G$ of degree $0$, the substitution $x = vy$ works the same way.)`, key_terms: [{ term: 'Homogeneous function', definition_md: r`$F(\lambda x, \lambda y) = \lambda^nF(x, y)$.` }, { term: 'Homogeneous equation', definition_md: r`$\dfrac{dy}{dx} = F(x, y)$ with $F$ homogeneous of degree $0$.` }], formulas: [{ latex: r`y = vx \;\Rightarrow\; \dfrac{dy}{dx} = v + x\dfrac{dv}{dx}`, label: 'Substitution' }], visual: homFlow, visuals: [homTable], topic_ids: [topic(3)] },
    { heading: '6. Linear equations: the integrating factor', body_md: r`**Standard form:** $\dfrac{dy}{dx} + Py = Q$, where $P$ and $Q$ are functions of $x$ (or constants).

**Integrating factor:** $\text{I.F.} = e^{\int P\,dx}$ (no constant needed).

**Solution:** $y \cdot \text{I.F.} = \int Q \cdot \text{I.F.}\,dx + C$.

Examples: $\dfrac{dy}{dx} + 3y = e^{-x}$ gives $y = \dfrac{e^{-x}}{2} + Ce^{-3x}$; $\cos x\dfrac{dy}{dx} + y\sin x = \cos^2 x$ (divide by $\cos x$ first) gives $y = (x + C)\cos x$.`, key_terms: [{ term: 'Linear equation', definition_md: r`$y$ and $\dfrac{dy}{dx}$ appear only to the first degree and are not multiplied together.` }, { term: 'Integrating factor', definition_md: r`$e^{\int P\,dx}$, which makes the left side the derivative of $y \cdot \text{I.F.}$` }], formulas: [{ latex: r`y \cdot e^{\int P\,dx} = \int Q\,e^{\int P\,dx}\,dx + C`, label: 'Linear in y' }], visual: ifTable, visuals: [linFlow], topic_ids: [topic(4)] },
    { heading: '7. Equations linear in x; choosing a method; applications', body_md: r`**Linear in $x$:** $\dfrac{dx}{dy} + Px = Q$ with $P$, $Q$ functions of $y$: $\text{I.F.} = e^{\int P\,dy}$ and $x \cdot \text{I.F.} = \int Q \cdot \text{I.F.}\,dy + C$. Example: $\dfrac{dx}{dy} + x = y + 1$ gives $x = y + Ce^{-y}$.

**Choosing a method:** separable? homogeneous of degree $0$? linear in $y$ or in $x$? An equation may fit more than one type.

**Applications:** cooling $\dfrac{dT}{dt} = -k(T - T_0)$ gives $T = T_0 + (T(0) - T_0)e^{-kt}$; a constant input with loss, $\dfrac{dC}{dt} + aC = b$, approaches the steady value $\dfrac{b}{a}$.`, key_terms: [{ term: 'Linear in x', definition_md: r`$\dfrac{dx}{dy} + Px = Q$ with $P$, $Q$ functions of $y$.` }], formulas: [{ latex: r`x \cdot e^{\int P\,dy} = \int Q\,e^{\int P\,dy}\,dy + C`, label: 'Linear in x' }], visual: methodFlow, visuals: [pCool, pDrip], topic_ids: [topic(4), topic(2)] },
  ],
  exam_tips_md: r`**How marks are awarded**
- *Order and degree (1–2 marks):* order and degree stated separately; "degree not defined" with the reason.
- *Verifying a solution (2 marks):* derivative(s) found, substitution, both sides shown equal.
- *Separable or homogeneous (3–5 marks):* separation or substitution, integration, constant, final form (particular solution if a condition is given).
- *Linear (3–5 marks):* standard form, integrating factor, integration (often by parts), constant, final answer.

**Common mistakes**
1. Reading the degree from a lower derivative, or giving a degree when a derivative sits inside $\sin$, $\log$ or $e^{(\cdot)}$.
2. Forgetting the constant of integration, or adding one on each side.
3. Using the initial condition before integrating.
4. After $y = vx$, writing $\dfrac{dy}{dx} = \dfrac{dv}{dx}$ instead of $v + x\dfrac{dv}{dx}$.
5. Leaving the answer in terms of $v$.
6. Reading $P$ before reaching the standard form (dividing by the coefficient of $\dfrac{dy}{dx}$), or losing the sign of $P$.
7. Adding a constant inside the integrating factor.
8. Writing $\log y$ where $y$ may be negative: use $\log|y|$.

*Not in the 2026–27 syllabus:* forming differential equations by eliminating arbitrary constants.`,
  status: 'draft', provenance: d1.provenance,
};

